css:
/* Antigravity Galaxy Theme — Dark */
.dark {
  --ag-star-light: #e8eefc;
  --ag-star-blue: #7aa2e3;
  --ag-star-ice: #b8cef8;
  --ag-stars:
    radial-gradient(circle at 38px 22px, color-mix(in srgb, var(--ag-star-light) 50%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 58px 8px, color-mix(in srgb, var(--ag-star-ice) 60%, transparent) 0.7px, transparent 1.3px),
    radial-gradient(circle at 84px 16px, color-mix(in srgb, var(--ag-star-blue) 55%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 126px 20px, color-mix(in srgb, var(--ag-star-light) 50%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 148px 11px, color-mix(in srgb, var(--ag-star-ice) 55%, transparent) 0.7px, transparent 1.3px),
    radial-gradient(circle at 170px 24px, color-mix(in srgb, var(--ag-star-light) 45%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 214px 18px, color-mix(in srgb, var(--ag-star-blue) 55%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 236px 8px, color-mix(in srgb, var(--ag-star-light) 60%, transparent) 0.7px, transparent 1.3px),
    radial-gradient(circle at 258px 20px, color-mix(in srgb, var(--ag-star-ice) 50%, transparent) 0.63px, transparent 1.17px),
    radial-gradient(circle at 26px 34px, color-mix(in srgb, var(--ag-star-light) 40%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 118px 34px, color-mix(in srgb, var(--ag-star-blue) 45%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 202px 32px, color-mix(in srgb, var(--ag-star-light) 45%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 268px 34px, color-mix(in srgb, var(--ag-star-light) 40%, transparent) 0.56px, transparent 1.04px),
    radial-gradient(circle at 92px 44px, color-mix(in srgb, var(--ag-star-light) 30%, transparent) 0.49px, transparent 0.91px),
    radial-gradient(circle at 182px 48px, color-mix(in srgb, var(--ag-star-blue) 30%, transparent) 0.49px, transparent 0.91px),
    radial-gradient(circle at 40px 52px, color-mix(in srgb, var(--ag-star-light) 25%, transparent) 0.49px, transparent 0.91px);
  --ag-twinkle:
    radial-gradient(circle at 14px 10px, color-mix(in srgb, var(--ag-star-light) 95%, transparent) 1.05px, transparent 1.95px),
    radial-gradient(circle at 104px 7px, color-mix(in srgb, var(--ag-star-ice) 90%, transparent) 1.05px, transparent 1.95px),
    radial-gradient(circle at 192px 9px, color-mix(in srgb, var(--ag-star-light) 90%, transparent) 1.05px, transparent 1.95px),
    radial-gradient(circle at 278px 11px, color-mix(in srgb, var(--ag-star-blue) 90%, transparent) 1px, transparent 1.85px),
    radial-gradient(circle at 62px 41px, color-mix(in srgb, var(--ag-star-light) 100%, transparent) 0.9px, transparent 1.8px),
    radial-gradient(7px 0.9px at 62px 41px, color-mix(in srgb, var(--ag-star-light) 95%, transparent), transparent),
    radial-gradient(0.9px 7px at 62px 41px, color-mix(in srgb, var(--ag-star-light) 95%, transparent), transparent),
    radial-gradient(circle at 160px 36px, color-mix(in srgb, var(--ag-star-ice) 100%, transparent) 0.9px, transparent 1.8px),
    radial-gradient(7px 0.9px at 160px 36px, color-mix(in srgb, var(--ag-star-ice) 95%, transparent), transparent),
    radial-gradient(0.9px 7px at 160px 36px, color-mix(in srgb, var(--ag-star-ice) 95%, transparent), transparent),
    radial-gradient(circle at 246px 26px, color-mix(in srgb, var(--ag-star-blue) 100%, transparent) 0.9px, transparent 1.8px),
    radial-gradient(7px 0.9px at 246px 26px, color-mix(in srgb, var(--ag-star-blue) 95%, transparent), transparent),
    radial-gradient(0.9px 7px at 246px 26px, color-mix(in srgb, var(--ag-star-blue) 95%, transparent), transparent);
}

.dark [data-workspace-area="conversation"],
.dark [data-settings-page-scroll] {
  background-color: #09090a !important;
  background-image:
    radial-gradient(
      ellipse 78% 48% at 50% 0%,
      rgba(28, 66, 146, 0.15) 0%,
      rgba(28, 66, 146, 0.132) 10%,
      rgba(28, 66, 146, 0.108) 20%,
      rgba(28, 66, 146, 0.082) 30%,
      rgba(28, 66, 146, 0.058) 40%,
      rgba(28, 66, 146, 0.038) 50%,
      rgba(28, 66, 146, 0.022) 60%,
      rgba(28, 66, 146, 0.01) 70%,
      rgba(28, 66, 146, 0.003) 80%,
      rgba(28, 66, 146, 0) 90%
    ) !important;
  background-repeat: no-repeat !important;
  background-attachment: local !important;
}

.dark .messages-timeline-scroll {
  background: transparent !important;
}

/* Seamless chat header blended into canvas */
.dark [data-chat-header] {
  background-color: transparent !important;
  background-image: none !important;
  border-bottom-color: transparent !important;
}

/* Unified solid sidebar with top Antigravity galaxy starfield */
.dark [data-slot="sidebar"] {
  background-color: #141417 !important;
  background-image: none !important;
  border-right-color: #222226 !important;
}

.dark [data-slot="sidebar-inner"] {
  background-color: #141417 !important;
  background-image: var(--ag-stars) !important;
  background-size: 288px 96px !important;
  background-repeat: repeat-x !important;
  background-position: 0 0 !important;
  border-right-color: #222226 !important;
  position: relative;
  isolation: isolate;
}

.dark [data-slot="sidebar-inner"]::before,
.dark [data-slot="sidebar-inner"]::after {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 112px;
  z-index: -1;
  pointer-events: none;
}

.dark [data-slot="sidebar-inner"]::before {
  background:
    radial-gradient(55% 80px at 92% 0, rgba(122, 162, 227, 0.14), transparent 75%),
    radial-gradient(50% 72px at 6% 0, rgba(56, 108, 204, 0.18), transparent 75%),
    linear-gradient(to bottom, rgba(28, 66, 146, 0.28), rgba(22, 48, 106, 0.10) 50%, transparent 100%);
}

.dark [data-slot="sidebar-inner"]::after {
  background-image: var(--ag-twinkle);
  background-size: 288px 96px;
  background-repeat: repeat-x;
  animation: ag-twinkle 4.8s ease-in-out infinite alternate;
}

@keyframes ag-twinkle {
  from { opacity: 0.45; }
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .dark [data-slot="sidebar-inner"]::after {
    animation: none;
    opacity: 0.85;
  }
}

/* Hide back/forward navigation arrows over the sidebar galaxy header */
[data-slot="sidebar-inner"] button:has(svg.lucide-arrow-left),
[data-slot="sidebar-inner"] button:has(svg.lucide-arrow-right),
[data-slot="sidebar-inner"] button[aria-label*="back" i],
[data-slot="sidebar-inner"] button[aria-label*="forward" i] {
  display: none !important;
}

/* Quieter, flatter sidebar rows */
.dark [data-thread-item] {
  border-radius: 8px !important;
  border-color: transparent !important;
}

.dark [data-thread-item]:hover {
  background-color: #1e1e22 !important;
}

.dark [data-thread-item][data-active="true"],
.dark [data-thread-item][aria-current="page"] {
  background-color: #232328 !important;
  background-image: none !important;
  border-color: transparent !important;
}

/* Antigravity-style darker, flatter rounded composer */
.dark [data-slot="composer-host"] {
  background-color: #121214 !important;
  background-image: none !important;
  border: 1px solid #242428 !important;
  border-radius: 18px !important;
  box-shadow: none !important;
  transition: border-color 150ms ease !important;
}

.dark [data-slot="composer-host"]:focus-within {
  border-color: #323239 !important;
  box-shadow: none !important;
}

.dark [data-chat-composer-form] {
  background-color: #151518 !important;
  border-radius: 16px !important;
}

/* High-contrast white send button in composer */
.dark [data-chat-composer-form] button[type="submit"]:not(:disabled) {
  background-color: #f4f4f6 !important;
  color: #101011 !important;
}

.dark [data-chat-composer-form] button[type="submit"]:not(:disabled):hover {
  background-color: #ffffff !important;
}

.dark [data-chat-composer-form] button[type="submit"]:disabled {
  background-color: #25252a !important;
  color: #787882 !important;
}

/* Messages, inline code, links & code blocks */
.dark [data-user-message-bubble] {
  background-color: #18181c !important;
  background-image: none !important;
  border: 1px solid #25252a !important;
  border-radius: 14px !important;
}

.dark .chat-markdown {
  color: #e8e8ec;
}

.dark .chat-markdown :not(pre) > code {
  background-color: #1a212e !important;
  color: #9bb7e8 !important;
  border: 1px solid rgba(122, 162, 227, 0.14) !important;
  border-radius: 5px !important;
}

.dark .chat-markdown a {
  color: #7aa2e3 !important;
}

.dark .chat-markdown a:hover {
  color: #9bbdf0 !important;
}

.dark .chat-markdown-codeblock {
  background-color: #111114 !important;
  border: 1px solid #222227 !important;
  border-radius: 10px !important;
}

/* Low-profile floating cards, popovers & menus */
.dark [data-thread-details-card],
.dark [data-slot="dialog-popup"],
.dark [data-slot="popover-popup"],
.dark [data-slot="menu-popup"] {
  background-color: #131316 !important;
  background-image: none !important;
  border-color: #232328 !important;
  border-radius: 12px !important;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5) !important;
}

.dark [data-slot="tooltip-popup"] {
  background-color: #19191d !important;
  border-color: #28282e !important;
  border-radius: 8px !important;
}

/* Antigravity Galaxy Theme — Light */
:root:not(.dark) [data-workspace-area="conversation"],
:root:not(.dark) [data-settings-page-scroll] {
  background-color: #fafafa !important;
  background-image:
    radial-gradient(
      ellipse 78% 48% at 50% 0%,
      rgba(64, 114, 212, 0.12) 0%,
      rgba(64, 114, 212, 0.085) 20%,
      rgba(64, 114, 212, 0.045) 45%,
      rgba(64, 114, 212, 0.015) 70%,
      rgba(64, 114, 212, 0) 90%
    ) !important;
  background-repeat: no-repeat !important;
}

:root:not(.dark) [data-chat-header] {
  background-color: transparent !important;
  border-bottom-color: transparent !important;
}

:root:not(.dark) [data-slot="sidebar"],
:root:not(.dark) [data-slot="sidebar-inner"] {
  background-color: #f3f3f5 !important;
  background-image: none !important;
}

:root:not(.dark) [data-thread-item] {
  border-radius: 8px !important;
}

:root:not(.dark) [data-slot="composer-host"] {
  background-color: #ffffff !important;
  border: 1px solid #e2e2e7 !important;
  border-radius: 18px !important;
  box-shadow: none !important;
}

:root:not(.dark) .chat-markdown :not(pre) > code {
  background-color: #e9effa !important;
  color: #2b4f8f !important;
  border: 1px solid rgba(74, 115, 196, 0.16) !important;
  border-radius: 5px !important;
}

:root:not(.dark) .chat-markdown a {
  color: #3b66b8 !important;
}

:root:not(.dark) [data-thread-details-card],
:root:not(.dark) [data-slot="dialog-popup"],
:root:not(.dark) [data-slot="popover-popup"],
:root:not(.dark) [data-slot="menu-popup"] {
  border-radius: 12px !important;
}

/* Crisper icons & minimal scrollbars */
svg.lucide {
  stroke-width: 1.55;
  stroke-linecap: round;
  stroke-linejoin: round;
}

[data-slot="scroll-area-thumb"] {
  border-radius: 9999px !important;
}

.dark ::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.dark ::-webkit-scrollbar-track {
  background: transparent;
}

.dark ::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
}

.dark ::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.22);
}
